ont-size: 14px;\n  color: #166534;\n}\n\n.balance-row.credit[_ngcontent-%COMP%] {\n  background: #fff7ed;\n  color: #9a3412;\n}\n\n.bal-amount[_ngcontent-%COMP%] {\n  font-size: 18px;\n}\n\n.action-btns[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 8px;\n  padding: 16px;\n  flex-wrap: wrap;\n}\n\n.btn-save-bill[_ngcontent-%COMP%] {\n  flex: 1;\n  background: #f59e0b;\n  color: #0f1117;\n  border: none;\n  padding: 12px;\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.btn-save-bill[_ngcontent-%COMP%]:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.btn-print[_ngcontent-%COMP%] {\n  background: #0f1117;\n  color: #fff;\n  border: none;\n  padding: 12px 14px;\n  border-radius: 8px;\n  cursor: pointer;\n  font-size: 13px;\n}\n\n.btn-clear[_ngcontent-%COMP%] {\n  background: #f8fafc;\n  border: 1px solid #d1d5db;\n  padding: 12px 14px;\n  border-radius: 8px;\n  cursor: pointer;\n  font-size: 13px;\n}\n\n.success-banner[_ngcontent-%COMP%] {\n  margin: 0 16px 16px;\n  background: #dcfce7;\n  color: #166534;\n  padding: 10px 14px;\n  border-radius: 8px;\n  font-size: 13px;\n}\n\n@media (max-width: 900px) {\n  .billing-screen[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
